def process(summerRainfall, bucksCreekSummerExceedance) -> pd.DataFrame:
    import pandas as pd

    yr = int(summerRainfall.loc[0, 'Year'])
    rain = float(summerRainfall.loc[0, 'SummerRainfall'])
    rate = float(bucksCreekSummerExceedance.loc[0, 'exceedance_rate_pct'])

    return pd.DataFrame([{
        'year_with_most_summer_rainfall': yr,
        'summer_rainfall': rain,
        'exceedance_rate_pct': round(rate, 2)
    }])
